function tg(string $method,array $data):array{$cfg=$GLOBALS['tgRuntime']['cfg'];if(isset($cfg['_telegram_request']))return $cfg['_telegram_request']($method,$data);$ch=curl_init('https://api.telegram.org/bot'.$cfg['telegram_token'].'/'.$method);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20,CURLOPT_POSTFIELDS=>$data]);$raw=curl_exec($ch);$err=curl_errno($ch);curl_close($ch);$j=json_decode((string)$raw,true);if($err||!($j['ok']??false))throw new RuntimeException('Telegram delivery failed');return $j['result'];}
function gemini(array $body,string $model,int $timeout=35):array{$cfg=$GLOBALS['tgRuntime']['cfg'];if(isset($cfg['_gemini_request']))return $cfg['_gemini_request']($body,$model);$ch=curl_init('https://generativelanguage.googleapis.com/v1beta/models/'.$model.':generateContent');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>12,CURLOPT_TIMEOUT=>$timeout,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$cfg['gemini_key']],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE)]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_errno($ch);curl_close($ch);if(($err||in_array($status,[429,500,502,503,504]))&&$model==='gemini-3.8-flash')return gemini($body,'gemini-3.5-flash-lite',20);if(($err||in_array($status,[429,500,502,503,504]))&&$model==='gemini-3.8-flash-tts')return gemini($body,'gemini-3.8-flash-lite-tts',25);if($err||$status!==200)throw new RuntimeException('Gemini request failed: '.$status.'/'.$err);$data=json_decode((string)$raw,true);if(!is_array($data))throw new RuntimeException('Gemini response invalid');return $data;}
function say(string $text):void{$chat=$GLOBALS['tgRuntime']['chat'];$text=str_replace('\\n',"\n",mb_substr($text,0,4000));tgJobStage('send_text');tg('sendMessage',['chat_id'=>$chat,'text'=>$text,'reply_markup'=>'{"remove_keyboard":true}']);$GLOBALS['tgRuntime']['text_delivered']=true;tgJobStage('text_delivered',true);}
function remember(string $input,string $reply,string $type='text'):void{
    extract($GLOBALS['tgRuntime'],EXTR_REFS);
    $existing=$incomingId?opsGetRecord($pdo,(int)$owner['id'],(int)$incomingId,'telegram')['data']:[];
    if(preg_match('/^(?:я владелец|вход владельца|мен иесімін)\s+\d{8}/iu',trim($input)))$input='[Вход владельца]';
    $data=array_merge($existing,['name'=>'Telegram · '.$chat,'chat_id'=>(string)$chat,'text'=>$input,'reply'=>$reply,'type'=>$type,'status'=>'done']);
    if($incomingId)opsPutRecord($pdo,$owner['id'],$incomingId,$data);else $incomingId=opsRecord($pdo,$owner['id'],'telegram',$data);
}
