function markVoiceReply($status){extract($GLOBALS['tgRuntime'],EXTR_REFS);if(!$incomingId)return;$q=$pdo->prepare('SELECT payload FROM aulieata_records WHERE id=? AND user_id=?');$q->execute([$incomingId,$owner['id']]);$d=json_decode($q->fetchColumn(),true);$d['audio_reply']=$status;$q=$pdo->prepare('UPDATE aulieata_records SET payload=? WHERE id=? AND user_id=?');$q->execute([json_encode($d,JSON_UNESCAPED_UNICODE),$incomingId,$owner['id']]);}

