      $q=$pdo->prepare('SELECT COUNT(*) FROM aulieata_tg_events WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 DAY)');$q->execute([$owner['id']]);if((int)$q->fetchColumn()>300)throw new RuntimeException('Daily bot limit reached');
      $parts=[];$inputType=isset($msg['voice'])?'voice':'text';$stage='incoming';tgJobStage($stage);$q=$pdo->prepare("INSERT INTO aulieata_records(user_id,kind,payload) VALUES(?,'telegram',?)");$q->execute([$owner['id'],json_encode(['name'=>'Telegram · '.$chat,'chat_id'=>$chat,'text'=>$inputType==='voice'?'[Голосовое сообщение]':$text,'reply'=>'Обрабатывается…','type'=>$inputType,'status'=>'processing','update_id'=>$updateId,'voice_file_id'=>$msg['voice']['file_id']??null],JSON_UNESCAPED_UNICODE)]);$incomingId=$pdo->lastInsertId();
      if(isset($msg['voice'])){
        if(($msg['voice']['file_size']??0)>8000000||($msg['voice']['duration']??0)>120){say('Отправьте голосовое сообщение до 2 минут и 8 МБ.');remember('[Голосовое сообщение]','Запрошено более короткое сообщение.','voice');$parts=[];}else{
          $stage='voice_file';tgJobStage($stage);$file=tg('getFile',['file_id'=>$msg['voice']['file_id']]);$remote=$file['file_path']??'';if(!preg_match('~^[a-zA-Z0-9_./-]+$~D',$remote)||str_contains($remote,'..'))throw new RuntimeException('Invalid voice path');
          $ch=curl_init('https://api.telegram.org/file/bot'.$cfg['telegram_token'].'/'.$remote);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20]);$audio=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($status!==200||!$audio||strlen($audio)>8000000)throw new RuntimeException('Voice download failed');
          $stage='transcription';tgJobStage($stage);$recognized=gemini(['contents'=>[['role'=>'user','parts'=>[['text'=>'Точно расшифруй речь на казахском, русском или их смеси. Верни только распознанный текст без ответа на вопрос. Если речь неразборчива, верни [неразборчиво].'],['inlineData'=>['mimeType'=>'audio/ogg','data'=>base64_encode($audio)]]]]],'generationConfig'=>['maxOutputTokens'=>1800]],'gemini-3.8-flash');$text='';foreach($recognized['candidates'][0]['content']['parts']??[] as $part)if(isset($part['text'])&&empty($part['thought']))$text.=$part['text'];$text=trim(mb_substr($text,0,6000));if(!$text||str_contains($text,'[неразборчиво]')){say('Не удалось разобрать речь. Запишите ещё раз ближе к микрофону или напишите вопрос.');remember('[Голосовое сообщение]','Речь неразборчива.','voice');$parts=[];}else{$parts=[['text'=>$text]];$inputType='voice';}
        }
