        $stage='history';tgJobStage($stage);$q=$pdo->prepare("SELECT payload FROM aulieata_records WHERE user_id=? AND kind='telegram' AND archived=0 AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.chat_id')) AS BINARY)=CAST(? AS BINARY) AND id<>? AND COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.status')) AS BINARY),CAST('done' AS BINARY))=CAST('done' AS BINARY) ORDER BY id DESC LIMIT 5");$q->execute([$owner['id'],$chat,$incomingId]);$previous=array_reverse($q->fetchAll());$context=[];foreach($previous as $r){$r=json_decode($r['payload'],true);if(!empty($r['owner_private']))continue;$context[]=['role'=>'user','parts'=>[['text'=>mb_substr($r['text'],0,2500)]]];$context[]=['role'=>'model','parts'=>[['text'=>mb_substr($r['reply'],0,3000)]]];}$context[]=['role'=>'user','parts'=>$parts];
        $stage='business_context';tgJobStage($stage);$catalog=publicCatalogData($pdo,(int)$owner['id'],$text);$system=businessBotSystem($pdo,$owner,$catalog,$text);$stage='operations';tgJobStage($stage);try{$handled=opsBotHandle($pdo,$owner,$chat,$text,$cfg,(int)$incomingId);}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;$handled='Не удалось выполнить действие: '.opsText($e->getMessage(),500).' Изменения не подтверждены; проверьте запрос или попросите сотрудника.';}
        $stage='answer';tgJobStage($stage);$reply=$handled;if($reply===null&&($botSettings['bot_mode']??'ai')!=='ai')$reply=botUnavailable(botKk($text));if($reply===null){try{$res=gemini(['systemInstruction'=>['parts'=>[['text'=>$system]]],'contents'=>$context,'generationConfig'=>['maxOutputTokens'=>1600]],'gemini-3.8-flash');$reply='';foreach($res['candidates'][0]['content']['parts']??[] as $p)if(isset($p['text'])&&empty($p['thought']))$reply.=$p['text'];if(!$reply)throw new RuntimeException('Empty answer');}catch(RuntimeException $e){$reply=botUnavailable(botKk($text));}}$reply=mb_substr($reply,0,3800);$stage='send_text';tgJobStage($stage);say($reply);remember($text,$reply,$inputType);
        $q=$pdo->prepare('SELECT voice_mode FROM aulieata_tg_preferences WHERE user_id=? AND chat_id=?');$q->execute([$owner['id'],$chat]);$voicePreference=$q->fetchColumn();if($voiceEnabled&&((int)$voicePreference===1||($voicePreference===false&&$inputType==='voice'))){
